var a=[{title:`Ce măsoară durata`,text:`Un plank de 30 de secunde, un wall sit de 40 de secunde și un interval rapid de ciclism de 20 de secunde folosesc toate un cronometru, dar antrenează lucruri diferite. Menținerile statice produc forță fără multă mișcare a articulațiilor, în timp ce seriile dinamice cronometrate repetă o mișcare. Același timp se poate simți foarte diferit în funcție de poziție, pârghie, sarcină și intensitate.`},{title:`Calitate, nu supraviețuire`,text:`La un plank, oprește-te când nu îți mai poți ține trunchiul controlat, chiar dacă cronometrul nu s-a terminat. La un wall sit, unghiul genunchilor și poziția picioarelor stabilesc dificultatea. La o atârnare contează priza și poziția umerilor. Să ții mai mult o poziție mai slabă poate face mai puțin pentru tine decât o menținere mai scurtă pe care o poți repeta în aceeași poziție.`},{title:`Cum progresezi`,text:`Începe cu un timp pe care îl poți repeta bine, de exemplu 15–20 de secunde. Apoi adaugă câteva secunde pe parcursul mai multor sesiuni, adaugă o serie sau treci la o variantă puțin mai grea. Schimbă un singur lucru principal pe rând. Odată ce o menținere este foarte lungă, adăugarea de rezistență sau o pârghie mai grea face de obicei mai mult decât urmărirea a câtorva minute.`},{title:`Serii cronometrate de condiție fizică`,text:`Un interval de lucru de 30 de secunde urmat de 60 de secunde de pauză nu este automat antrenament pe intervale de intensitate mare. Intensitatea depinde de ritmul sau efortul tău în timpul lucrului. Dacă ești începător, alege o viteză pe care o poți controla și destulă pauză ca să continui să te miști bine.`},{title:`Exemplu`,text:`Fă trei planșe laterale de 20 de secunde pe fiecare parte, cu 40–60 de secunde de pauză. Când fiecare menținere rămâne stabilă, treci la 25 de secunde. Dacă șoldurile îți cad la 12 secunde, scurtează menținerea sau treci la o planșă laterală cu sprijin pe genunchi.`},{title:`Folosind TrainUp`,text:`Exercițiile cronometrate din planul tău vin cu un timp de menținere, iar ecranul antrenamentului are un cronometru de menținere. Dacă schimbi varianta, scrie asta în notițele antrenamentului și nu compara timpii din poziții diferite ale corpului ca și cum ar fi același test.`}];var t=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Îndrumări OMS privind activitatea`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var n={sections:a,sources:t};export{n as default,a as sections,t as sources};